using DevInn.Application.Features.Financial.Expenses.GetExpenses;using DevInn.WebApi.Common;using Mediator;namespace DevInn.WebApi.Endpoints.Financial.Expenses;public sealed class GetExpensesEndpoint : IEndpoint{    private const string Route = "api/v1/expenses";    public void MapEndpoint(IEndpointRouteBuilder app)    {        app.MapGet(Route, async (ISender sender, CancellationToken ct) =>            {                var result = await sender.Send(new GetExpensesQuery(), ct);                return result.ToOk();            })            .WithTags(Tags.Expenses)            .WithName("List Expenses")            .Produces<ApiResource<ExpenseResponse[]>>()            .Produces<ApiProblemDetails>(StatusCodes.Status400BadRequest)            .RequireAuthorization();    }}